"""Customer insight endpoints for the account team."""

from __future__ import annotations

from orders.application.errors import CustomerNotFound
from orders.application.insights_service import InsightsService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, service: InsightsService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            summaries = self._service.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {
            "customer_id": customer_id,
            "orders": [{"order_id": s.order.order_id, "status": s.order.status,
                        "total_cents": s.total_cents} for s in summaries],
        })

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            order_count, lifetime_value_cents = self._service.lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": order_count,
                              "lifetime_value_cents": lifetime_value_cents})

def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_customer_with_no_orders_gets_empty_list(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_orders_are_newest_first_with_status(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    third = order(shop, "c1", ("LAMP", 1)).body["order_id"]
    shop.orders.handle_cancel(second)
    body = shop.insights.handle_order_history("c1").body
    assert body["customer_id"] == "c1"
    assert body["orders"] == [
        {"order_id": third, "status": "placed", "total_cents": 6_000},
        {"order_id": second, "status": "cancelled", "total_cents": 600},
        {"order_id": first, "status": "placed", "total_cents": 2_500},
    ]


def test_totals_include_discount_and_match_order_summary(shop):
    # Gold customer c2: 15% off subtotals of $100.00 or more.
    created = order(shop, "c2", ("LAMP", 5)).body["order_id"]  # 30_000 subtotal
    history = shop.insights.handle_order_history("c2").body["orders"]
    summary = shop.orders.handle_get(created).body
    assert history == [{"order_id": created, "status": "placed", "total_cents": summary["total_cents"]}]
    assert history[0]["total_cents"] == 25_500


def test_other_customers_orders_are_excluded(shop):
    order(shop, "c1", ("BOOK", 1))
    order(shop, "c2", ("PEN", 1))
    orders = shop.insights.handle_order_history("c2").body["orders"]
    assert [o["total_cents"] for o in orders] == [300]


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_with_no_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_orders(shop):
    order(shop, "c1", ("BOOK", 1))                              # 2_500, placed
    cancelled = order(shop, "c1", ("PEN", 2)).body["order_id"]  # 600, cancelled
    order(shop, "c1", ("LAMP", 5))                              # 30_000 subtotal, placed
    shop.orders.handle_cancel(cancelled)
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    # Standard tier: 30_000 subtotal gets 10% off -> 27_000; plus 2_500 -> 29_500.
    assert response.body == {"customer_id": "c1", "order_count": 2, "lifetime_value_cents": 29_500}


def test_lifetime_value_uses_discounted_totals(shop):
    order(shop, "c2", ("LAMP", 5))  # gold: 30_000 -> 25_500
    order(shop, "c2", ("BOOK", 1))  # 2_500
    response = shop.insights.handle_lifetime_value("c2")
    assert response.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": 28_000}

